const markLostPreviewLeaseAndWithdrawDomainsV1 = `-- name: MarkLostPreviewLeaseAndWithdrawDomainsV1 :many
WITH candidates AS (
  SELECT source.id
  FROM preview_leases AS source
  WHERE source.terminal_state = 'active'
    AND source.lease_deadline > $1
    AND source.owner_last_seen_at <= $2
  ORDER BY source.owner_last_seen_at, source.id
  LIMIT $3
  FOR UPDATE SKIP LOCKED
), lost AS (
  UPDATE preview_leases AS p
  SET allocation_state = 'released', edge_state = 'released', terminal_state = 'owner_lost',
      generation = p.generation + 1, stopped_at = $1
  FROM candidates
  WHERE p.id = candidates.id
  RETURNING p.id, p.account_id, p.generation
), withdrawn AS (
  UPDATE preview_domains AS d
  SET ownership_state = 'expired',
      certificate_state = CASE WHEN d.certificate_state = 'not_applicable' THEN 'not_applicable' ELSE 'revoked' END,
      conflict_state = 'quarantined', quarantine_until = $4,
      deleted_at = $1, generation = d.generation + 1, updated_at = $1
  FROM lost
  WHERE d.preview_id = lost.id AND d.account_id = lost.account_id
    AND d.preview_generation < lost.generation AND d.deleted_at IS NULL
  RETURNING d.id
)
SELECT id, account_id, generation FROM lost
`

type MarkLostPreviewLeaseAndWithdrawDomainsV1Params struct {
	Now             time.Time
	OwnerCutoff     time.Time
	RowLimit        int32
	QuarantineUntil sql.NullTime
}

type MarkLostPreviewLeaseAndWithdrawDomainsV1Row struct {
	ID         string
	AccountID  string
	Generation int64
}

